/**
 * SnowballSystem — handles snowball creation, physics, and collision.
 * Player throws by clicking/triggering, direction from camera/controller.
 */
import {
	createSystem,
	Mesh,
	MeshStandardMaterial,
	SphereGeometry,
	Vector3,
	Color,
} from '@iwsdk/core';
import {
	gameState,
	GameState,
	snowballs,
	enemies,
	systemRefs,
	snowballGeo,
	giantSnowballGeo,
	NEON_CYAN,
	NEON_PINK,
	SnowballData,
	EnemyType,
	DIFFICULTY_CONFIGS,
	ENEMY_CONFIGS,
	ARENA_RADIUS,
} from './game-state.js';

const THROW_SPEED = 18;
const GRAVITY = -9.8;
const SNOWBALL_LIFETIME = 4;
const THROW_COOLDOWN = 0.35;
const RAPID_FIRE_COOLDOWN = 0.1;
const ENEMY_HIT_RADIUS = 0.6;
const PLAYER_HIT_RADIUS = 0.8;

const _dir = new Vector3();
const _pos = new Vector3();
const _tmp = new Vector3();

export class SnowballSystem extends createSystem({}) {
	private throwCooldown = 0;
	private wasMouseDown = false;

	init(): void {
		// Mouse / touch for browser mode
		const canvas = this.world.renderer.domElement;
		canvas.addEventListener('mousedown', () => {
			if (gameState.state === GameState.PLAYING && this.throwCooldown <= 0) {
				this.throwSnowball();
				this.throwCooldown = gameState.rapidFireActive ? RAPID_FIRE_COOLDOWN : THROW_COOLDOWN;
			}
		});
		canvas.addEventListener('touchstart', () => {
			if (gameState.state === GameState.PLAYING && this.throwCooldown <= 0) {
				this.throwSnowball();
				this.throwCooldown = gameState.rapidFireActive ? RAPID_FIRE_COOLDOWN : THROW_COOLDOWN;
			}
		});
	}

	update(delta: number): void {
		if (gameState.state !== GameState.PLAYING) return;

		this.throwCooldown -= delta;

		// XR: check trigger via input actions
		const actions = this.world.input?.actions;
		if (actions) {
			const triggerDown = actions.getButtonDown('interaction.select');
			if (triggerDown && this.throwCooldown <= 0) {
				this.throwSnowball();
				this.throwCooldown = gameState.rapidFireActive ? RAPID_FIRE_COOLDOWN : THROW_COOLDOWN;
			}
		}

		// Update all snowballs
		this.updateSnowballs(delta);
	}

	private throwSnowball(): void {
		if (!systemRefs.snowballGroup) return;

		// Get camera direction
		const camera = this.world.camera;
		camera.getWorldDirection(_dir);
		camera.getWorldPosition(_pos);

		const isGiant = gameState.giantSnowballActive;
		const geo = isGiant ? giantSnowballGeo : snowballGeo;

		const mat = new MeshStandardMaterial({
			color: 0xffffff,
			roughness: 0.4,
			metalness: 0.1,
			emissive: new Color(isGiant ? NEON_PINK : NEON_CYAN),
			emissiveIntensity: 0.4,
		});

		const mesh = new Mesh(geo, mat);
		mesh.position.copy(_pos).add(_dir.clone().multiplyScalar(0.5));

		// Add slight upward arc
		const velocity = _dir.clone().multiplyScalar(THROW_SPEED);
		velocity.y += 2;

		systemRefs.snowballGroup.add(mesh);

		snowballs.push({
			mesh,
			velocity,
			damage: isGiant ? 3 : 1,
			lifetime: SNOWBALL_LIFETIME,
			isPlayerOwned: true,
			isGiant,
		});

		// Fire event for audio
		window.dispatchEvent(new CustomEvent('snowball-throw', { detail: { isGiant } }));
	}

	/** Called by EnemySystem to create enemy snowballs */
	static createEnemySnowball(
		origin: Vector3,
		targetPos: Vector3,
		damage: number,
		type: EnemyType,
	): void {
		if (!systemRefs.snowballGroup) return;

		const dir = _tmp.copy(targetPos).sub(origin).normalize();
		const speed = type === EnemyType.SPEEDY ? 14 : type === EnemyType.BOMBER ? 10 : 12;

		const isBomber = type === EnemyType.BOMBER;
		const geo = isBomber ? giantSnowballGeo : snowballGeo;
		const mat = new MeshStandardMaterial({
			color: isBomber ? 0xff4444 : 0xccccdd,
			roughness: 0.5,
			emissive: new Color(isBomber ? 0xff2200 : 0x334455),
			emissiveIntensity: isBomber ? 0.6 : 0.2,
		});

		const mesh = new Mesh(geo, mat);
		mesh.position.copy(origin);

		const velocity = dir.clone().multiplyScalar(speed);
		// Add arc to reach target
		const dist = origin.distanceTo(targetPos);
		velocity.y += dist * 0.3;

		systemRefs.snowballGroup.add(mesh);

		snowballs.push({
			mesh,
			velocity,
			damage,
			lifetime: SNOWBALL_LIFETIME,
			isPlayerOwned: false,
			isGiant: isBomber,
		});
	}

	private updateSnowballs(delta: number): void {
		const playerPos = new Vector3();
		this.world.camera.getWorldPosition(playerPos);

		for (let i = snowballs.length - 1; i >= 0; i--) {
			const sb = snowballs[i];
			sb.lifetime -= delta;

			// Apply gravity
			sb.velocity.y += GRAVITY * delta;

			// Move
			sb.mesh.position.x += sb.velocity.x * delta;
			sb.mesh.position.y += sb.velocity.y * delta;
			sb.mesh.position.z += sb.velocity.z * delta;

			// Spin
			sb.mesh.rotation.x += delta * 5;
			sb.mesh.rotation.z += delta * 3;

			let shouldRemove = false;

			// Ground collision
			if (sb.mesh.position.y < 0) {
				shouldRemove = true;
				window.dispatchEvent(new CustomEvent('snowball-impact', {
					detail: { x: sb.mesh.position.x, y: 0, z: sb.mesh.position.z, isGiant: sb.isGiant },
				}));
			}

			// Out of bounds
			if (
				Math.abs(sb.mesh.position.x) > ARENA_RADIUS + 5 ||
				Math.abs(sb.mesh.position.z) > ARENA_RADIUS + 5
			) {
				shouldRemove = true;
			}

			// Lifetime
			if (sb.lifetime <= 0) {
				shouldRemove = true;
			}

			// Player snowball hitting enemies
			if (sb.isPlayerOwned) {
				for (let j = enemies.length - 1; j >= 0; j--) {
					const enemy = enemies[j];
					if (enemy.isDying) continue;

					const dist = sb.mesh.position.distanceTo(enemy.group.position);
					const hitRadius = ENEMY_HIT_RADIUS * (enemy.type === EnemyType.BOSS ? 1.5 : 1.0);

					if (dist < hitRadius) {
						enemy.health -= sb.damage;
						enemy.hitFlashTimer = 0.15;

						if (sb.isGiant) {
							// Giant snowball area damage
							for (let k = enemies.length - 1; k >= 0; k--) {
								if (k === j || enemies[k].isDying) continue;
								const aoeDist = sb.mesh.position.distanceTo(enemies[k].group.position);
								if (aoeDist < 2.5) {
									enemies[k].health -= 1;
									enemies[k].hitFlashTimer = 0.15;
								}
							}
						}

						if (enemy.health <= 0) {
							enemy.isDying = true;
							enemy.deathTimer = 0.5;
							gameState.enemiesKilled++;
							gameState.totalEnemiesKilled++;
							gameState.enemiesRemaining--;

							// Scoring
							const config = ENEMY_CONFIGS[enemy.type];
							const diffConfig = DIFFICULTY_CONFIGS[gameState.difficulty];
							const comboMult = 1 + gameState.combo * 0.1;
							const points = Math.floor(
								config.points * comboMult * diffConfig.scoreMultiplier,
							);
							gameState.score += points;
							gameState.combo++;
							gameState.comboTimer = 3;
							if (gameState.combo > gameState.maxCombo) {
								gameState.maxCombo = gameState.combo;
							}

							window.dispatchEvent(new CustomEvent('enemy-hit', {
								detail: { killed: true, points, combo: gameState.combo },
							}));
						} else {
							window.dispatchEvent(new CustomEvent('enemy-hit', {
								detail: { killed: false },
							}));
						}

						shouldRemove = true;
						break;
					}
				}
			}

			// Enemy snowball hitting player
			if (!sb.isPlayerOwned) {
				const dist = sb.mesh.position.distanceTo(playerPos);
				if (dist < PLAYER_HIT_RADIUS) {
					if (!gameState.shieldActive) {
						const diffConfig = DIFFICULTY_CONFIGS[gameState.difficulty];
						const damage = sb.damage * diffConfig.enemyDamageMult;
						gameState.health -= damage;
						gameState.combo = 0;

						window.dispatchEvent(new CustomEvent('player-hit', {
							detail: { damage },
						}));

						if (gameState.health <= 0) {
							gameState.health = 0;
							gameState.state = GameState.GAME_OVER;
							window.dispatchEvent(new CustomEvent('game-over'));
						}
					} else {
						window.dispatchEvent(new CustomEvent('shield-block'));
					}
					shouldRemove = true;
				}
			}

			if (shouldRemove) {
				systemRefs.snowballGroup?.remove(sb.mesh);
				sb.mesh.geometry.dispose();
				(sb.mesh.material as MeshStandardMaterial).dispose();
				snowballs.splice(i, 1);
			}
		}
	}
}

/**
 * EnemySystem — snowman enemy AI, spawning, behavior.
 */
import {
	createSystem,
	Group,
	Mesh,
	MeshStandardMaterial,
	MeshBasicMaterial,
	SphereGeometry,
	CylinderGeometry,
	ConeGeometry,
	BoxGeometry,
	Vector3,
	Color,
	PointLight,
} from '@iwsdk/core';
import {
	gameState,
	GameState,
	enemies,
	systemRefs,
	EnemyData,
	EnemyType,
	ENEMY_CONFIGS,
	DIFFICULTY_CONFIGS,
	SPAWN_DISTANCE,
	NEON_CYAN,
	NEON_PURPLE,
	NEON_PINK,
	NEON_BLUE,
} from './game-state.js';
import { SnowballSystem } from './snowball-system.js';

const _playerPos = new Vector3();
const _dir = new Vector3();
const _throwOrigin = new Vector3();

export class EnemySystem extends createSystem({}) {
	init(): void {}

	update(delta: number): void {
		if (gameState.state !== GameState.PLAYING) return;

		this.world.camera.getWorldPosition(_playerPos);

		const diffConfig = DIFFICULTY_CONFIGS[gameState.difficulty];
		const isFrozen = gameState.freezeActive;

		for (let i = enemies.length - 1; i >= 0; i--) {
			const enemy = enemies[i];

			// Death animation
			if (enemy.isDying) {
				enemy.deathTimer -= delta;
				enemy.group.scale.multiplyScalar(0.93);
				enemy.group.rotation.y += delta * 8;
				enemy.group.position.y -= delta * 0.5;

				if (enemy.deathTimer <= 0) {
					systemRefs.enemyGroup?.remove(enemy.group);
					this.disposeGroup(enemy.group);
					enemies.splice(i, 1);
				}
				continue;
			}

			// Hit flash
			if (enemy.hitFlashTimer > 0) {
				enemy.hitFlashTimer -= delta;
				this.setEnemyEmissive(enemy.group, enemy.hitFlashTimer > 0 ? 0xff4444 : 0x000000);
			}

			// Movement (unless frozen)
			const speedMult = isFrozen ? 0.15 : diffConfig.enemySpeedMult;
			const dist = enemy.group.position.distanceTo(_playerPos);

			if (dist > 4) {
				// Move toward player
				_dir
					.copy(_playerPos)
					.sub(enemy.group.position)
					.normalize();
				_dir.y = 0;

				// Add some lateral movement for interest
				const lateralPhase =
					Math.sin(Date.now() * 0.001 + enemy.group.position.x * 2) * 0.3;
				_dir.x += lateralPhase;
				_dir.normalize();

				enemy.group.position.x += _dir.x * enemy.speed * speedMult * delta;
				enemy.group.position.z += _dir.z * enemy.speed * speedMult * delta;
			} else if (dist < 3) {
				// Too close - back away
				_dir
					.copy(enemy.group.position)
					.sub(_playerPos)
					.normalize();
				_dir.y = 0;
				enemy.group.position.x += _dir.x * enemy.speed * speedMult * delta * 0.5;
				enemy.group.position.z += _dir.z * enemy.speed * speedMult * delta * 0.5;
			}

			// Face player
			_dir.copy(_playerPos).sub(enemy.group.position);
			_dir.y = 0;
			if (_dir.lengthSq() > 0.01) {
				enemy.group.rotation.y = Math.atan2(_dir.x, _dir.z);
			}

			// Throwing
			const throwMult = isFrozen ? 0.3 : diffConfig.enemyThrowRateMult;
			enemy.throwTimer -= delta * throwMult;

			if (enemy.throwTimer <= 0 && dist < 15) {
				enemy.throwTimer = enemy.throwCooldown;

				// Calculate throw origin (head level)
				const headY = enemy.type === EnemyType.BOSS ? 3.5 : 1.5;
				_throwOrigin.copy(enemy.group.position);
				_throwOrigin.y = headY * (enemy.type === EnemyType.BOSS ? 1 : ENEMY_CONFIGS[enemy.type].scale);

				const config = ENEMY_CONFIGS[enemy.type];
				SnowballSystem.createEnemySnowball(
					_throwOrigin,
					_playerPos,
					config.damage,
					enemy.type,
				);

				window.dispatchEvent(new CustomEvent('enemy-throw'));
			}

			// Bobbing animation
			const bob = Math.sin(Date.now() * 0.003 + enemy.group.position.x) * 0.03;
			enemy.group.position.y = bob;
		}
	}

	private setEnemyEmissive(group: Group, color: number): void {
		group.traverse((child) => {
			if (child instanceof Mesh) {
				const mat = child.material as MeshStandardMaterial;
				if (mat.emissive) {
					mat.emissive.setHex(color);
					mat.emissiveIntensity = color === 0x000000 ? 0 : 0.8;
				}
			}
		});
	}

	private disposeGroup(group: Group): void {
		group.traverse((child) => {
			if (child instanceof Mesh) {
				child.geometry.dispose();
				if (child.material instanceof MeshStandardMaterial || child.material instanceof MeshBasicMaterial) {
					child.material.dispose();
				}
			}
		});
	}

	static spawnEnemy(type: EnemyType): void {
		if (!systemRefs.enemyGroup) return;

		const config = ENEMY_CONFIGS[type];
		const group = new Group();

		// Random spawn position around arena edge
		const angle = Math.random() * Math.PI * 2;
		group.position.set(
			Math.cos(angle) * SPAWN_DISTANCE,
			0,
			Math.sin(angle) * SPAWN_DISTANCE,
		);

		const s = config.scale;

		// Body (bottom sphere)
		const bodyGeo = new SphereGeometry(0.45 * s, 12, 8);
		const bodyMat = new MeshStandardMaterial({
			color: config.bodyColor,
			roughness: 0.8,
		});
		const body = new Mesh(bodyGeo, bodyMat);
		body.position.y = 0.45 * s;
		group.add(body);

		// Torso (middle sphere)
		const torsoGeo = new SphereGeometry(0.35 * s, 12, 8);
		const torsoMat = new MeshStandardMaterial({
			color: config.bodyColor,
			roughness: 0.8,
		});
		const torso = new Mesh(torsoGeo, torsoMat);
		torso.position.y = 1.0 * s;
		group.add(torso);

		// Head
		const headGeo = new SphereGeometry(0.25 * s, 12, 8);
		const headMat = new MeshStandardMaterial({
			color: config.bodyColor,
			roughness: 0.8,
		});
		const head = new Mesh(headGeo, headMat);
		head.position.y = 1.45 * s;
		group.add(head);

		// Eyes (small dark spheres)
		const eyeGeo = new SphereGeometry(0.04 * s, 6, 4);
		const eyeMat = new MeshBasicMaterial({ color: 0x111111 });
		for (const side of [-1, 1]) {
			const eye = new Mesh(eyeGeo, eyeMat.clone());
			eye.position.set(side * 0.08 * s, 1.5 * s, 0.2 * s);
			group.add(eye);
		}

		// Neon eye glow
		const glowColor =
			type === EnemyType.BOSS
				? NEON_PURPLE
				: type === EnemyType.BOMBER
					? NEON_PINK
					: type === EnemyType.SPEEDY
						? NEON_BLUE
						: NEON_CYAN;
		const eyeLight = new PointLight(glowColor, 0.4, 2);
		eyeLight.position.set(0, 1.5 * s, 0.25 * s);
		group.add(eyeLight);

		// Carrot nose
		const noseGeo = new ConeGeometry(0.04 * s, 0.2 * s, 6);
		const noseMat = new MeshStandardMaterial({ color: 0xff6622 });
		const nose = new Mesh(noseGeo, noseMat);
		nose.position.set(0, 1.42 * s, 0.26 * s);
		nose.rotation.x = -Math.PI / 2;
		group.add(nose);

		// Hat
		const hatBaseGeo = new CylinderGeometry(0.3 * s, 0.3 * s, 0.04 * s, 12);
		const hatMat = new MeshStandardMaterial({
			color: config.hatColor,
			roughness: 0.5,
		});
		const hatBase = new Mesh(hatBaseGeo, hatMat);
		hatBase.position.y = 1.7 * s;
		group.add(hatBase);

		const hatTopGeo = new CylinderGeometry(0.18 * s, 0.22 * s, 0.3 * s, 12);
		const hatTop = new Mesh(hatTopGeo, hatMat.clone());
		hatTop.position.y = 1.87 * s;
		group.add(hatTop);

		// Hat neon band
		const bandGeo = new CylinderGeometry(0.23 * s, 0.23 * s, 0.03 * s, 12);
		const bandMat = new MeshBasicMaterial({
			color: glowColor,
			transparent: true,
			opacity: 0.9,
		});
		const band = new Mesh(bandGeo, bandMat);
		band.position.y = 1.75 * s;
		group.add(band);

		// Stick arms
		const armMat = new MeshStandardMaterial({ color: 0x4a3222, roughness: 0.9 });
		for (const side of [-1, 1]) {
			const armGeo = new CylinderGeometry(0.02 * s, 0.025 * s, 0.6 * s, 6);
			const arm = new Mesh(armGeo, armMat.clone());
			arm.position.set(side * 0.4 * s, 1.0 * s, 0);
			arm.rotation.z = side * 0.8;
			group.add(arm);
		}

		// Buttons
		const btnGeo = new SphereGeometry(0.03 * s, 6, 4);
		const btnMat = new MeshBasicMaterial({ color: 0x111111 });
		for (let b = 0; b < 3; b++) {
			const btn = new Mesh(btnGeo, btnMat.clone());
			btn.position.set(0, (0.7 + b * 0.15) * s, 0.35 * s);
			group.add(btn);
		}

		// Boss: add crown
		if (type === EnemyType.BOSS) {
			const crownGeo = new CylinderGeometry(0.15, 0.2, 0.15, 5);
			const crownMat = new MeshBasicMaterial({
				color: 0xffdd00,
				transparent: true,
				opacity: 0.9,
			});
			const crown = new Mesh(crownGeo, crownMat);
			crown.position.y = 2.05 * s;
			group.add(crown);

			const crownLight = new PointLight(0xffdd00, 0.5, 4);
			crownLight.position.y = 2.1 * s;
			group.add(crownLight);
		}

		systemRefs.enemyGroup.add(group);

		enemies.push({
			group,
			type,
			health: config.health,
			maxHealth: config.health,
			throwCooldown: config.throwCooldown,
			throwTimer: config.throwCooldown * (0.5 + Math.random() * 0.5),
			speed: config.speed,
			targetPos: new Vector3(),
			isDying: false,
			deathTimer: 0,
			hitFlashTimer: 0,
		});
	}
}

/**
 * GameSystem — wave management, power-ups, game flow controller.
 */
import {
	createSystem,
	Mesh,
	MeshStandardMaterial,
	MeshBasicMaterial,
	SphereGeometry,
	OctahedronGeometry,
	Vector3,
	Color,
	PointLight,
} from '@iwsdk/core';
import {
	gameState,
	GameState,
	enemies,
	snowballs,
	powerUps,
	activePowerUps,
	systemRefs,
	EnemyType,
	PowerUpType,
	PowerUpData,
	ActivePowerUp,
	getWaveEnemyCount,
	isBossWave,
	resetGameState,
	NEON_CYAN,
	NEON_PINK,
	NEON_GREEN,
	NEON_PURPLE,
	ARENA_RADIUS,
} from './game-state.js';
import { EnemySystem } from './enemy-system.js';

const WAVE_DELAY = 3;
const POWER_UP_SPAWN_INTERVAL = 15;
const COMBO_TIMEOUT = 3;

export class GameSystem extends createSystem({}) {
	private waveDelay = 0;
	private powerUpTimer = 0;
	private spawnQueue: EnemyType[] = [];
	private spawnTimer = 0;
	private spawnInterval = 0.8;

	init(): void {
		// Load high score
		try {
			const saved = localStorage.getItem('neon-snowball-highscore');
			if (saved) gameState.highScore = parseInt(saved, 10);
		} catch {}
	}

	update(delta: number): void {
		// Combo timer
		if (gameState.comboTimer > 0) {
			gameState.comboTimer -= delta;
			if (gameState.comboTimer <= 0) {
				gameState.combo = 0;
			}
		}

		// Active power-ups
		for (let i = activePowerUps.length - 1; i >= 0; i--) {
			const ap = activePowerUps[i];
			ap.remaining -= delta;
			if (ap.remaining <= 0) {
				this.deactivatePowerUp(ap.type);
				activePowerUps.splice(i, 1);
			}
		}

		if (gameState.state === GameState.PLAYING) {
			this.updatePlaying(delta);
		} else if (gameState.state === GameState.WAVE_COMPLETE) {
			this.updateWaveComplete(delta);
		}
	}

	private updatePlaying(delta: number): void {
		// Spawn queued enemies
		if (this.spawnQueue.length > 0) {
			this.spawnTimer -= delta;
			if (this.spawnTimer <= 0) {
				const type = this.spawnQueue.shift()!;
				EnemySystem.spawnEnemy(type);
				this.spawnTimer = this.spawnInterval;
			}
		}

		// Power-up spawning
		this.powerUpTimer -= delta;
		if (this.powerUpTimer <= 0 && powerUps.length < 2) {
			this.spawnPowerUp();
			this.powerUpTimer = POWER_UP_SPAWN_INTERVAL;
		}

		// Update power-up bobbing
		this.updatePowerUps(delta);

		// Check wave complete
		if (
			gameState.enemiesRemaining <= 0 &&
			this.spawnQueue.length === 0 &&
			enemies.length === 0
		) {
			gameState.state = GameState.WAVE_COMPLETE;
			this.waveDelay = WAVE_DELAY;
			window.dispatchEvent(new CustomEvent('wave-complete', {
				detail: { wave: gameState.wave },
			}));
		}
	}

	private updateWaveComplete(delta: number): void {
		this.waveDelay -= delta;
		if (this.waveDelay <= 0) {
			this.startNextWave();
		}
	}

	startNextWave(): void {
		gameState.wave++;
		gameState.state = GameState.PLAYING;
		gameState.enemiesKilled = 0;

		const count = getWaveEnemyCount(gameState.wave);
		gameState.waveEnemiesTotal = count;
		gameState.enemiesRemaining = count;

		// Build spawn queue
		this.spawnQueue = [];

		if (isBossWave(gameState.wave)) {
			// Boss wave: boss + some minions
			this.spawnQueue.push(EnemyType.BOSS);
			for (let i = 0; i < count - 1; i++) {
				this.spawnQueue.push(this.randomEnemyType());
			}
		} else {
			for (let i = 0; i < count; i++) {
				this.spawnQueue.push(this.randomEnemyType());
			}
		}

		this.spawnTimer = 0;
		this.spawnInterval = Math.max(0.3, 0.8 - gameState.wave * 0.02);
		this.powerUpTimer = 8;

		window.dispatchEvent(new CustomEvent('wave-start', {
			detail: { wave: gameState.wave, count },
		}));
	}

	private randomEnemyType(): EnemyType {
		const wave = gameState.wave;
		const roll = Math.random();

		if (wave >= 8 && roll < 0.15) return EnemyType.BOMBER;
		if (wave >= 5 && roll < 0.3) return EnemyType.TANK;
		if (wave >= 3 && roll < 0.5) return EnemyType.SPEEDY;
		return EnemyType.BASIC;
	}

	private spawnPowerUp(): void {
		if (!systemRefs.powerUpGroup) return;

		const types = [PowerUpType.GIANT, PowerUpType.RAPID, PowerUpType.SHIELD, PowerUpType.FREEZE];
		const type = types[Math.floor(Math.random() * types.length)];

		const colors: Record<PowerUpType, number> = {
			[PowerUpType.GIANT]: NEON_PINK,
			[PowerUpType.RAPID]: NEON_CYAN,
			[PowerUpType.SHIELD]: NEON_GREEN,
			[PowerUpType.FREEZE]: NEON_PURPLE,
		};

		const geo = new OctahedronGeometry(0.2, 0);
		const mat = new MeshStandardMaterial({
			color: colors[type],
			emissive: new Color(colors[type]),
			emissiveIntensity: 0.6,
			transparent: true,
			opacity: 0.85,
			metalness: 0.3,
			roughness: 0.2,
		});
		const mesh = new Mesh(geo, mat);

		// Random position in arena
		const angle = Math.random() * Math.PI * 2;
		const dist = 3 + Math.random() * 5;
		mesh.position.set(Math.cos(angle) * dist, 1.0, Math.sin(angle) * dist);

		// Add glow light
		const glow = new PointLight(colors[type], 0.5, 4);
		glow.position.copy(mesh.position);
		systemRefs.powerUpGroup.add(glow);

		systemRefs.powerUpGroup.add(mesh);

		powerUps.push({
			mesh,
			type,
			lifetime: 20,
			bobPhase: Math.random() * Math.PI * 2,
		});
	}

	private updatePowerUps(delta: number): void {
		const playerPos = new Vector3();
		this.world.camera.getWorldPosition(playerPos);

		for (let i = powerUps.length - 1; i >= 0; i--) {
			const pu = powerUps[i];
			pu.lifetime -= delta;
			pu.bobPhase += delta * 2;

			// Bobbing and rotation
			pu.mesh.position.y = 1.0 + Math.sin(pu.bobPhase) * 0.15;
			pu.mesh.rotation.y += delta * 1.5;
			pu.mesh.rotation.x += delta * 0.8;

			// Check player proximity
			const dist = pu.mesh.position.distanceTo(playerPos);
			if (dist < 1.5) {
				this.activatePowerUp(pu.type);
				this.removePowerUp(i);
				continue;
			}

			if (pu.lifetime <= 0) {
				this.removePowerUp(i);
			}
		}
	}

	private removePowerUp(index: number): void {
		const pu = powerUps[index];
		systemRefs.powerUpGroup?.remove(pu.mesh);
		pu.mesh.geometry.dispose();
		(pu.mesh.material as MeshStandardMaterial).dispose();
		powerUps.splice(index, 1);
	}

	private activatePowerUp(type: PowerUpType): void {
		const duration = type === PowerUpType.SHIELD ? 8 : type === PowerUpType.FREEZE ? 6 : 10;

		// Remove existing of same type
		for (let i = activePowerUps.length - 1; i >= 0; i--) {
			if (activePowerUps[i].type === type) {
				this.deactivatePowerUp(type);
				activePowerUps.splice(i, 1);
			}
		}

		activePowerUps.push({ type, remaining: duration });

		switch (type) {
			case PowerUpType.GIANT:
				gameState.giantSnowballActive = true;
				break;
			case PowerUpType.RAPID:
				gameState.rapidFireActive = true;
				break;
			case PowerUpType.SHIELD:
				gameState.shieldActive = true;
				break;
			case PowerUpType.FREEZE:
				gameState.freezeActive = true;
				break;
		}

		window.dispatchEvent(new CustomEvent('powerup-collected', { detail: { type } }));
	}

	private deactivatePowerUp(type: PowerUpType): void {
		switch (type) {
			case PowerUpType.GIANT:
				gameState.giantSnowballActive = false;
				break;
			case PowerUpType.RAPID:
				gameState.rapidFireActive = false;
				break;
			case PowerUpType.SHIELD:
				gameState.shieldActive = false;
				break;
			case PowerUpType.FREEZE:
				gameState.freezeActive = false;
				break;
		}
	}

	/** Called externally to start a new game */
	startNewGame(): void {
		// Clear all existing objects
		this.clearAll();
		resetGameState();
		gameState.state = GameState.PLAYING;
		this.startNextWave();
	}

	/** Called externally to restart */
	restart(): void {
		this.clearAll();
		resetGameState();
		gameState.state = GameState.PLAYING;
		this.startNextWave();
	}

	clearAll(): void {
		// Remove all snowballs
		for (const sb of snowballs) {
			systemRefs.snowballGroup?.remove(sb.mesh);
			sb.mesh.geometry.dispose();
			(sb.mesh.material as MeshStandardMaterial).dispose();
		}
		snowballs.length = 0;

		// Remove all enemies
		for (const e of enemies) {
			systemRefs.enemyGroup?.remove(e.group);
		}
		enemies.length = 0;

		// Remove all power-ups
		for (const pu of powerUps) {
			systemRefs.powerUpGroup?.remove(pu.mesh);
			pu.mesh.geometry.dispose();
			(pu.mesh.material as MeshStandardMaterial).dispose();
		}
		powerUps.length = 0;

		activePowerUps.length = 0;
		this.spawnQueue = [];
	}

	saveHighScore(): void {
		if (gameState.score > gameState.highScore) {
			gameState.highScore = gameState.score;
			try {
				localStorage.setItem('neon-snowball-highscore', String(gameState.highScore));
			} catch {}
		}
	}
}

/**
 * EffectsSystem — particle effects for impacts, power-ups, visual feedback.
 */
import {
	createSystem,
	Mesh,
	MeshBasicMaterial,
	SphereGeometry,
	Vector3,
	Color,
} from '@iwsdk/core';
import {
	gameState,
	GameState,
	particles,
	systemRefs,
	particleGeo,
	ParticleData,
	NEON_CYAN,
	NEON_PINK,
	NEON_GREEN,
	NEON_PURPLE,
	SNOW_WHITE,
} from './game-state.js';

const MAX_PARTICLES = 300;

export class EffectsSystem extends createSystem({}) {
	private shieldIndicator: Mesh | null = null;
	private freezeOverlay: Mesh | null = null;

	init(): void {
		// Snowball impact
		window.addEventListener('snowball-impact', (e: Event) => {
			const d = (e as CustomEvent).detail;
			this.spawnImpact(d.x, d.y, d.z, d.isGiant);
		});

		// Enemy killed
		window.addEventListener('enemy-hit', (e: Event) => {
			const d = (e as CustomEvent).detail;
			if (d.killed) {
				// Extra particles for kill
				this.spawnBurst(0, 1, 0, 20, NEON_CYAN, 0.5);
			}
		});

		// Player hit
		window.addEventListener('player-hit', () => {
			this.flashScreen(0xff4444);
		});

		// Shield block
		window.addEventListener('shield-block', () => {
			this.flashScreen(NEON_GREEN);
		});

		// Power-up collected
		window.addEventListener('powerup-collected', (e: Event) => {
			const d = (e as CustomEvent).detail;
			const colors: Record<string, number> = {
				GIANT: NEON_PINK,
				RAPID: NEON_CYAN,
				SHIELD: NEON_GREEN,
				FREEZE: NEON_PURPLE,
			};
			this.spawnBurst(0, 1.5, 0, 15, colors[d.type] || NEON_CYAN, 0.6);
		});

		// Create shield indicator mesh
		const shieldGeo = new SphereGeometry(1.0, 16, 12);
		const shieldMat = new MeshBasicMaterial({
			color: NEON_GREEN,
			transparent: true,
			opacity: 0,
			wireframe: true,
		});
		this.shieldIndicator = new Mesh(shieldGeo, shieldMat);
		this.shieldIndicator.visible = false;
		this.world.scene.add(this.shieldIndicator);
	}

	update(delta: number): void {
		// Update particles
		for (let i = particles.length - 1; i >= 0; i--) {
			const p = particles[i];
			p.lifetime -= delta;

			p.mesh.position.x += p.velocity.x * delta;
			p.mesh.position.y += p.velocity.y * delta;
			p.mesh.position.z += p.velocity.z * delta;

			// Gravity
			p.velocity.y -= 3 * delta;

			// Fade
			const alpha = Math.max(0, p.lifetime / p.maxLifetime);
			(p.mesh.material as MeshBasicMaterial).opacity = alpha;
			p.mesh.scale.setScalar(alpha);

			if (p.lifetime <= 0) {
				systemRefs.particleGroup?.remove(p.mesh);
				p.mesh.geometry.dispose();
				(p.mesh.material as MeshBasicMaterial).dispose();
				particles.splice(i, 1);
			}
		}

		// Shield indicator follows player
		if (this.shieldIndicator) {
			if (gameState.shieldActive) {
				const cam = this.world.camera;
				const pos = new Vector3();
				cam.getWorldPosition(pos);
				this.shieldIndicator.position.copy(pos);
				this.shieldIndicator.visible = true;
				(this.shieldIndicator.material as MeshBasicMaterial).opacity =
					0.15 + Math.sin(Date.now() * 0.005) * 0.1;
			} else {
				this.shieldIndicator.visible = false;
			}
		}
	}

	private spawnImpact(x: number, y: number, z: number, isGiant: boolean): void {
		const count = isGiant ? 20 : 10;
		this.spawnBurst(x, y, z, count, SNOW_WHITE, isGiant ? 0.6 : 0.4);
	}

	private spawnBurst(
		x: number,
		y: number,
		z: number,
		count: number,
		color: number,
		speed: number,
	): void {
		if (!systemRefs.particleGroup) return;
		if (particles.length >= MAX_PARTICLES) return;

		const actualCount = Math.min(count, MAX_PARTICLES - particles.length);

		for (let i = 0; i < actualCount; i++) {
			const mat = new MeshBasicMaterial({
				color,
				transparent: true,
				opacity: 1,
			});
			const mesh = new Mesh(particleGeo, mat);
			mesh.position.set(x, y + 0.1, z);

			const vel = new Vector3(
				(Math.random() - 0.5) * speed * 4,
				Math.random() * speed * 3 + 1,
				(Math.random() - 0.5) * speed * 4,
			);

			const lifetime = 0.3 + Math.random() * 0.6;

			systemRefs.particleGroup.add(mesh);
			particles.push({
				mesh,
				velocity: vel,
				lifetime,
				maxLifetime: lifetime,
			});
		}
	}

	private flashScreen(color: number): void {
		// Brief visual indicator — could add screen overlay in future
		// For now, emit particles near camera
		const cam = this.world.camera;
		const pos = new Vector3();
		cam.getWorldPosition(pos);
		this.spawnBurst(pos.x, pos.y, pos.z, 8, color, 0.3);
	}
}

/**
 * UISystem — manages all UIKitMLAsset panels.
 */
import {
	createSystem,
	UIKitMLAsset,
	VisibilityState,
} from '@iwsdk/core';
import {
	gameState,
	GameState,
	Difficulty,
	activePowerUps,
	PowerUpType,
} from './game-state.js';
import { GameSystem } from './game-system.js';

// Module-level reference so other systems can trigger UI updates
let uiSystemInstance: UISystem | null = null;

export function getUISystem(): UISystem | null {
	return uiSystemInstance;
}

export class UISystem extends createSystem({}) {
	// Panels
	private menuPanel: UIKitMLAsset | null = null;
	private hudPanel: UIKitMLAsset | null = null;
	private pausePanel: UIKitMLAsset | null = null;
	private resultsPanel: UIKitMLAsset | null = null;
	private settingsPanel: UIKitMLAsset | null = null;
	private tutorialPanel: UIKitMLAsset | null = null;

	// Game system reference
	private gameSystem: GameSystem | null = null;

	private lastState: GameState = GameState.MENU;
	private updateTimer = 0;

	init(): void {
		uiSystemInstance = this;

		// Get panels
		this.menuPanel = this.world.getSceneObject<UIKitMLAsset>('menu-panel') ?? null;
		this.hudPanel = this.world.getSceneObject<UIKitMLAsset>('hud-panel') ?? null;
		this.pausePanel = this.world.getSceneObject<UIKitMLAsset>('pause-panel') ?? null;
		this.resultsPanel = this.world.getSceneObject<UIKitMLAsset>('results-panel') ?? null;
		this.settingsPanel = this.world.getSceneObject<UIKitMLAsset>('settings-panel') ?? null;
		this.tutorialPanel = this.world.getSceneObject<UIKitMLAsset>('tutorial-panel') ?? null;

		// Get game system
		this.gameSystem = this.world.getSystem(GameSystem) as GameSystem | null;

		// Wire menu buttons
		this.wireMenuPanel();
		this.wirePausePanel();
		this.wireResultsPanel();
		this.wireSettingsPanel();
		this.wireTutorialPanel();

		// XR button
		this.wireXRButton();

		// Show menu initially
		this.showPanel('menu');

		// Listen for events
		window.addEventListener('game-over', () => {
			this.gameSystem?.saveHighScore();
			this.showPanel('results');
			this.updateResultsPanel(true);
		});

		window.addEventListener('wave-complete', () => {
			this.showPanel('results');
			this.updateResultsPanel(false);
		});

		window.addEventListener('wave-start', () => {
			this.showPanel('hud');
		});

		// Keyboard pause
		window.addEventListener('keydown', (e: Event) => {
			const ke = e as KeyboardEvent;
			if (ke.key === 'Escape' || ke.key === 'p' || ke.key === 'P') {
				this.togglePause();
			}
		});
	}

	update(delta: number): void {
		this.updateTimer += delta;

		// Update HUD every 100ms
		if (this.updateTimer >= 0.1 && gameState.state === GameState.PLAYING) {
			this.updateTimer = 0;
			this.updateHUD();
		}
	}

	private showPanel(panel: 'menu' | 'hud' | 'pause' | 'results' | 'settings' | 'tutorial'): void {
		if (this.menuPanel) this.menuPanel.visible = panel === 'menu';
		if (this.hudPanel) this.hudPanel.visible = panel === 'hud';
		if (this.pausePanel) this.pausePanel.visible = panel === 'pause';
		if (this.resultsPanel) this.resultsPanel.visible = panel === 'results';
		if (this.settingsPanel) this.settingsPanel.visible = panel === 'settings';
		if (this.tutorialPanel) this.tutorialPanel.visible = panel === 'tutorial';
	}

	private wireMenuPanel(): void {
		if (!this.menuPanel) return;

		const playBtn = this.menuPanel.getElementById('btn-play');
		const settingsBtn = this.menuPanel.getElementById('btn-settings');
		const tutorialBtn = this.menuPanel.getElementById('btn-tutorial');

		playBtn?.addEventListener('click', () => {
			this.gameSystem?.startNewGame();
			this.showPanel('hud');
		});

		settingsBtn?.addEventListener('click', () => {
			this.showPanel('settings');
		});

		tutorialBtn?.addEventListener('click', () => {
			this.showPanel('tutorial');
		});

		// Update high score on menu
		const hsEl = this.menuPanel.getElementById('high-score');
		if (hsEl) {
			hsEl.setProperties({ text: `HIGH SCORE: ${gameState.highScore}` });
		}
	}

	private wirePausePanel(): void {
		if (!this.pausePanel) return;

		const resumeBtn = this.pausePanel.getElementById('btn-resume');
		const restartBtn = this.pausePanel.getElementById('btn-restart');
		const quitBtn = this.pausePanel.getElementById('btn-quit');

		resumeBtn?.addEventListener('click', () => {
			gameState.state = GameState.PLAYING;
			this.showPanel('hud');
		});

		restartBtn?.addEventListener('click', () => {
			this.gameSystem?.restart();
			this.showPanel('hud');
		});

		quitBtn?.addEventListener('click', () => {
			this.gameSystem?.saveHighScore();
			this.gameSystem?.clearAll();
			gameState.state = GameState.MENU;
			this.showPanel('menu');
			this.updateMenuHighScore();
		});
	}

	private wireResultsPanel(): void {
		if (!this.resultsPanel) return;

		const continueBtn = this.resultsPanel.getElementById('btn-continue');
		const restartBtn = this.resultsPanel.getElementById('btn-restart');
		const menuBtn = this.resultsPanel.getElementById('btn-menu');

		continueBtn?.addEventListener('click', () => {
			if (gameState.state === GameState.GAME_OVER) {
				// Restart
				this.gameSystem?.restart();
			} else {
				// Continue to next wave
				gameState.state = GameState.PLAYING;
				this.gameSystem?.startNextWave();
			}
			this.showPanel('hud');
		});

		restartBtn?.addEventListener('click', () => {
			this.gameSystem?.restart();
			this.showPanel('hud');
		});

		menuBtn?.addEventListener('click', () => {
			this.gameSystem?.saveHighScore();
			this.gameSystem?.clearAll();
			gameState.state = GameState.MENU;
			this.showPanel('menu');
			this.updateMenuHighScore();
		});
	}

	private wireSettingsPanel(): void {
		if (!this.settingsPanel) return;

		const easyBtn = this.settingsPanel.getElementById('btn-easy');
		const normalBtn = this.settingsPanel.getElementById('btn-normal');
		const hardBtn = this.settingsPanel.getElementById('btn-hard');
		const backBtn = this.settingsPanel.getElementById('btn-back');

		easyBtn?.addEventListener('click', () => {
			gameState.difficulty = Difficulty.EASY;
			this.updateDifficultyDisplay();
		});

		normalBtn?.addEventListener('click', () => {
			gameState.difficulty = Difficulty.NORMAL;
			this.updateDifficultyDisplay();
		});

		hardBtn?.addEventListener('click', () => {
			gameState.difficulty = Difficulty.HARD;
			this.updateDifficultyDisplay();
		});

		backBtn?.addEventListener('click', () => {
			this.showPanel('menu');
		});
	}

	private wireTutorialPanel(): void {
		if (!this.tutorialPanel) return;

		const backBtn = this.tutorialPanel.getElementById('btn-back');
		backBtn?.addEventListener('click', () => {
			this.showPanel('menu');
		});
	}

	private wireXRButton(): void {
		if (!this.menuPanel || !this.world.xrEnabled) return;

		const xrBtn = this.menuPanel.getElementById('btn-xr');
		if (xrBtn) {
			xrBtn.addEventListener('click', () => this.world.launchXR());
		}

		// Hide/show based on VR state
		this.cleanupFuncs.push(
			this.world.visibilityState.subscribe((state) => {
				const is2D = state === VisibilityState.NonImmersive;
				if (xrBtn) {
					xrBtn.setProperties({ display: is2D ? 'flex' : 'none' });
				}
			}),
		);
	}

	private togglePause(): void {
		if (gameState.state === GameState.PLAYING) {
			gameState.state = GameState.PAUSED;
			this.showPanel('pause');
		} else if (gameState.state === GameState.PAUSED) {
			gameState.state = GameState.PLAYING;
			this.showPanel('hud');
		}
	}

	private updateHUD(): void {
		if (!this.hudPanel) return;

		const scoreEl = this.hudPanel.getElementById('score');
		const healthEl = this.hudPanel.getElementById('health');
		const healthBarEl = this.hudPanel.getElementById('health-bar');
		const waveEl = this.hudPanel.getElementById('wave');
		const comboEl = this.hudPanel.getElementById('combo');
		const enemiesEl = this.hudPanel.getElementById('enemies');
		const powerupEl = this.hudPanel.getElementById('powerup');

		if (scoreEl) scoreEl.setProperties({ text: `${gameState.score}` });
		if (waveEl) waveEl.setProperties({ text: `WAVE ${gameState.wave}` });
		if (enemiesEl) enemiesEl.setProperties({ text: `${gameState.enemiesRemaining} LEFT` });

		// Health
		const healthPct = Math.max(0, gameState.health / gameState.maxHealth);
		if (healthEl) {
			healthEl.setProperties({ text: `${Math.ceil(gameState.health)}` });
		}
		if (healthBarEl) {
			const barWidth = Math.floor(healthPct * 200);
			const barColor =
				healthPct > 0.5
					? 'rgba(68,255,136,0.8)'
					: healthPct > 0.25
						? 'rgba(255,221,68,0.8)'
						: 'rgba(255,68,68,0.8)';
			healthBarEl.setProperties({ width: barWidth, backgroundColor: barColor });
		}

		// Combo
		if (comboEl) {
			if (gameState.combo > 1) {
				comboEl.setProperties({
					text: `${gameState.combo}x COMBO`,
					display: 'flex',
				});
			} else {
				comboEl.setProperties({ display: 'none' });
			}
		}

		// Active power-up
		if (powerupEl) {
			if (activePowerUps.length > 0) {
				const ap = activePowerUps[0];
				const names: Record<PowerUpType, string> = {
					[PowerUpType.GIANT]: '🔴 GIANT',
					[PowerUpType.RAPID]: '⚡ RAPID',
					[PowerUpType.SHIELD]: '🛡️ SHIELD',
					[PowerUpType.FREEZE]: '❄️ FREEZE',
				};
				powerupEl.setProperties({
					text: `${names[ap.type]} ${ap.remaining.toFixed(1)}s`,
					display: 'flex',
				});
			} else {
				powerupEl.setProperties({ display: 'none' });
			}
		}
	}

	private updateResultsPanel(isGameOver: boolean): void {
		if (!this.resultsPanel) return;

		const titleEl = this.resultsPanel.getElementById('title');
		const scoreEl = this.resultsPanel.getElementById('score');
		const waveEl = this.resultsPanel.getElementById('wave');
		const comboEl = this.resultsPanel.getElementById('max-combo');
		const killsEl = this.resultsPanel.getElementById('kills');
		const continueBtn = this.resultsPanel.getElementById('btn-continue');

		if (titleEl) {
			titleEl.setProperties({
				text: isGameOver ? 'GAME OVER' : 'WAVE COMPLETE!',
			});
		}
		if (scoreEl) {
			scoreEl.setProperties({ text: `SCORE: ${gameState.score}` });
		}
		if (waveEl) {
			waveEl.setProperties({
				text: isGameOver
					? `REACHED WAVE ${gameState.wave}`
					: `WAVE ${gameState.wave} CLEARED`,
			});
		}
		if (comboEl) {
			comboEl.setProperties({ text: `MAX COMBO: ${gameState.maxCombo}x` });
		}
		if (killsEl) {
			killsEl.setProperties({
				text: `ENEMIES DEFEATED: ${gameState.totalEnemiesKilled}`,
			});
		}
		if (continueBtn) {
			const el = this.resultsPanel.getElementById('btn-continue-text');
			if (el) {
				el.setProperties({
					text: isGameOver ? 'PLAY AGAIN' : 'NEXT WAVE',
				});
			}
		}
	}

	private updateDifficultyDisplay(): void {
		if (!this.settingsPanel) return;
		const current = this.settingsPanel.getElementById('current-difficulty');
		if (current) {
			current.setProperties({ text: `CURRENT: ${gameState.difficulty}` });
		}
	}

	private updateMenuHighScore(): void {
		if (!this.menuPanel) return;
		const hsEl = this.menuPanel.getElementById('high-score');
		if (hsEl) {
			hsEl.setProperties({ text: `HIGH SCORE: ${gameState.highScore}` });
		}
	}
}

/**
 * ArenaSystem — builds the winter wonderland environment.
 * Snow ground, forts with neon trim, pine trees, street lamps, frozen pond,
 * falling snow particles, aurora borealis sky.
 */
import {
	createSystem,
	Group,
	Object3D,
	Mesh,
	MeshStandardMaterial,
	MeshBasicMaterial,
	PlaneGeometry,
	BoxGeometry,
	CylinderGeometry,
	ConeGeometry,
	SphereGeometry,
	CircleGeometry,
	RingGeometry,
	PointLight,
	DirectionalLight,
	AmbientLight,
	Color,
	DoubleSide,
	Vector3,
	FogExp2,
} from '@iwsdk/core';
import {
	systemRefs,
	ARENA_RADIUS,
	NEON_CYAN,
	NEON_BLUE,
	NEON_PURPLE,
	NEON_PINK,
	WARM_YELLOW,
	SNOW_WHITE,
	ICE_BLUE,
} from './game-state.js';

export class ArenaSystem extends createSystem({}) {
	private snowParticles: { mesh: Mesh; vel: Vector3; baseY: number }[] = [];
	private auroraLights: PointLight[] = [];
	private time = 0;

	init(): void {
		const scene = this.world.scene;
		systemRefs.scene = scene;

		// Container groups
		const arenaGroup = new Group();
		arenaGroup.name = 'arena';
		scene.add(arenaGroup);
		systemRefs.arenaGroup = arenaGroup;

		const snowballGroup = new Group();
		snowballGroup.name = 'snowballs';
		scene.add(snowballGroup);
		systemRefs.snowballGroup = snowballGroup;

		const enemyGroup = new Group();
		enemyGroup.name = 'enemies';
		scene.add(enemyGroup);
		systemRefs.enemyGroup = enemyGroup;

		const particleGroup = new Group();
		particleGroup.name = 'particles';
		scene.add(particleGroup);
		systemRefs.particleGroup = particleGroup;

		const powerUpGroup = new Group();
		powerUpGroup.name = 'powerups';
		scene.add(powerUpGroup);
		systemRefs.powerUpGroup = powerUpGroup;

		// Lighting
		this.setupLighting(scene);

		// Ground
		this.buildGround(arenaGroup);

		// Forts
		this.buildForts(arenaGroup);

		// Trees
		this.buildTrees(arenaGroup);

		// Street lamps
		this.buildLamps(arenaGroup);

		// Frozen pond
		this.buildPond(arenaGroup);

		// Snow piles (ammo indicators)
		this.buildSnowPiles(arenaGroup);

		// Fog
		scene.fog = new FogExp2(0x0a1428, 0.02);

		// Falling snow
		this.initFallingSnow(scene);
	}

	private setupLighting(scene: Object3D): void {
		// Ambient
		const ambient = new AmbientLight(0x334466, 0.4);
		scene.add(ambient);

		// Main directional (moonlight)
		const moon = new DirectionalLight(0x8899cc, 0.6);
		moon.position.set(5, 15, -5);
		scene.add(moon);

		// Fill from below (snow reflection)
		const fill = new DirectionalLight(0x445577, 0.2);
		fill.position.set(-3, -2, 3);
		scene.add(fill);

		// Aurora borealis lights (cycle colors)
		const auroraColors = [0x00ff88, 0x4488ff, 0x8844ff, 0x00ffcc];
		for (let i = 0; i < 4; i++) {
			const light = new PointLight(auroraColors[i], 0.3, 50);
			const angle = (i / 4) * Math.PI * 2;
			light.position.set(
				Math.cos(angle) * 20,
				12 + Math.random() * 5,
				Math.sin(angle) * 20,
			);
			scene.add(light);
			this.auroraLights.push(light);
		}
	}

	private buildGround(parent: Group): void {
		// Snow ground
		const groundGeo = new PlaneGeometry(60, 60, 20, 20);
		const groundMat = new MeshStandardMaterial({
			color: SNOW_WHITE,
			roughness: 0.85,
			metalness: 0.05,
			emissive: new Color(0x112233),
			emissiveIntensity: 0.1,
		});
		const ground = new Mesh(groundGeo, groundMat);
		ground.rotation.x = -Math.PI / 2;
		ground.position.y = 0;
		ground.receiveShadow = true;
		parent.add(ground);

		// Subtle grid lines on snow (neon blue)
		for (let i = -6; i <= 6; i++) {
			const lineGeo = new BoxGeometry(30, 0.005, 0.02);
			const lineMat = new MeshBasicMaterial({
				color: NEON_CYAN,
				transparent: true,
				opacity: 0.08,
			});
			const line = new Mesh(lineGeo, lineMat);
			line.position.set(0, 0.005, i * 2.5);
			parent.add(line);

			const line2 = new Mesh(lineGeo.clone(), lineMat.clone());
			line2.rotation.y = Math.PI / 2;
			line2.position.set(i * 2.5, 0.005, 0);
			parent.add(line2);
		}
	}

	private buildForts(parent: Group): void {
		const fortPositions = [
			{ x: -5, z: -4, rot: 0.3 },
			{ x: 5, z: -5, rot: -0.2 },
			{ x: -4, z: 4, rot: -0.4 },
			{ x: 6, z: 3, rot: 0.5 },
		];

		for (const pos of fortPositions) {
			const fort = new Group();
			fort.position.set(pos.x, 0, pos.z);
			fort.rotation.y = pos.rot;

			// Main snow wall
			const wallGeo = new BoxGeometry(2.5, 1.0, 0.5);
			const wallMat = new MeshStandardMaterial({
				color: SNOW_WHITE,
				roughness: 0.9,
				metalness: 0.0,
			});
			const wall = new Mesh(wallGeo, wallMat);
			wall.position.y = 0.5;
			fort.add(wall);

			// Side walls
			for (const side of [-1, 1]) {
				const sideGeo = new BoxGeometry(0.5, 0.8, 1.2);
				const sideWall = new Mesh(sideGeo, wallMat.clone());
				sideWall.position.set(side * 1.2, 0.4, -0.5);
				fort.add(sideWall);
			}

			// Neon trim on top
			const trimGeo = new BoxGeometry(2.6, 0.04, 0.06);
			const trimMat = new MeshBasicMaterial({
				color: NEON_CYAN,
				transparent: true,
				opacity: 0.9,
			});
			const trim = new Mesh(trimGeo, trimMat);
			trim.position.set(0, 1.02, 0);
			fort.add(trim);

			// Neon glow
			const glow = new PointLight(NEON_CYAN, 0.3, 4);
			glow.position.set(0, 1.1, 0);
			fort.add(glow);

			parent.add(fort);
		}
	}

	private buildTrees(parent: Group): void {
		const treePositions = [
			{ x: -9, z: -8 },
			{ x: 9, z: -7 },
			{ x: -8, z: 7 },
			{ x: 10, z: 6 },
			{ x: -12, z: 0 },
			{ x: 12, z: -2 },
			{ x: 0, z: -11 },
			{ x: -6, z: -10 },
			{ x: 7, z: 10 },
			{ x: -11, z: -5 },
		];

		for (const pos of treePositions) {
			const tree = new Group();
			tree.position.set(pos.x, 0, pos.z);
			const scale = 0.8 + Math.random() * 0.5;
			tree.scale.setScalar(scale);

			// Trunk
			const trunkGeo = new CylinderGeometry(0.12, 0.18, 1.5, 8);
			const trunkMat = new MeshStandardMaterial({
				color: 0x4a3222,
				roughness: 0.9,
			});
			const trunk = new Mesh(trunkGeo, trunkMat);
			trunk.position.y = 0.75;
			tree.add(trunk);

			// Foliage layers (3 cones)
			const foliageMat = new MeshStandardMaterial({
				color: 0x1a4422,
				roughness: 0.8,
				emissive: new Color(0x003311),
				emissiveIntensity: 0.2,
			});
			const layerData = [
				{ y: 1.8, r: 1.2, h: 1.5 },
				{ y: 2.6, r: 0.9, h: 1.3 },
				{ y: 3.2, r: 0.6, h: 1.1 },
			];
			for (const ld of layerData) {
				const coneGeo = new ConeGeometry(ld.r, ld.h, 8);
				const cone = new Mesh(coneGeo, foliageMat.clone());
				cone.position.y = ld.y;
				tree.add(cone);
			}

			// Snow caps
			const snowMat = new MeshStandardMaterial({
				color: 0xffffff,
				roughness: 0.95,
			});
			for (const ld of layerData) {
				const capGeo = new ConeGeometry(ld.r * 0.7, 0.15, 8);
				const cap = new Mesh(capGeo, snowMat.clone());
				cap.position.y = ld.y + ld.h * 0.4;
				tree.add(cap);
			}

			parent.add(tree);
		}
	}

	private buildLamps(parent: Group): void {
		const lampPositions = [
			{ x: -3, z: -7 },
			{ x: 3, z: -7 },
			{ x: -7, z: 0 },
			{ x: 7, z: 0 },
			{ x: -3, z: 7 },
			{ x: 3, z: 7 },
		];

		for (const pos of lampPositions) {
			const lamp = new Group();
			lamp.position.set(pos.x, 0, pos.z);

			// Pole
			const poleGeo = new CylinderGeometry(0.04, 0.06, 3.0, 8);
			const poleMat = new MeshStandardMaterial({
				color: 0x222222,
				metalness: 0.8,
				roughness: 0.3,
			});
			const pole = new Mesh(poleGeo, poleMat);
			pole.position.y = 1.5;
			lamp.add(pole);

			// Lantern housing
			const housingGeo = new BoxGeometry(0.25, 0.3, 0.25);
			const housingMat = new MeshStandardMaterial({
				color: 0x111111,
				metalness: 0.9,
				roughness: 0.2,
			});
			const housing = new Mesh(housingGeo, housingMat);
			housing.position.y = 3.15;
			lamp.add(housing);

			// Lamp glow sphere
			const glowGeo = new SphereGeometry(0.1, 8, 6);
			const glowMat = new MeshBasicMaterial({
				color: WARM_YELLOW,
				transparent: true,
				opacity: 0.9,
			});
			const glow = new Mesh(glowGeo, glowMat);
			glow.position.y = 3.15;
			lamp.add(glow);

			// Point light
			const light = new PointLight(WARM_YELLOW, 0.8, 8);
			light.position.y = 3.15;
			lamp.add(light);

			// Base
			const baseGeo = new CylinderGeometry(0.15, 0.2, 0.1, 8);
			const baseMesh = new Mesh(baseGeo, poleMat.clone());
			baseMesh.position.y = 0.05;
			lamp.add(baseMesh);

			parent.add(lamp);
		}
	}

	private buildPond(parent: Group): void {
		// Frozen pond
		const pondGeo = new CircleGeometry(2.5, 32);
		const pondMat = new MeshStandardMaterial({
			color: ICE_BLUE,
			roughness: 0.1,
			metalness: 0.5,
			transparent: true,
			opacity: 0.7,
			emissive: new Color(0x224466),
			emissiveIntensity: 0.3,
		});
		const pond = new Mesh(pondGeo, pondMat);
		pond.rotation.x = -Math.PI / 2;
		pond.position.set(6, 0.01, -1);
		parent.add(pond);

		// Ice edge ring
		const ringGeo = new RingGeometry(2.3, 2.6, 32);
		const ringMat = new MeshBasicMaterial({
			color: NEON_CYAN,
			transparent: true,
			opacity: 0.3,
			side: DoubleSide,
		});
		const ring = new Mesh(ringGeo, ringMat);
		ring.rotation.x = -Math.PI / 2;
		ring.position.set(6, 0.02, -1);
		parent.add(ring);
	}

	private buildSnowPiles(parent: Group): void {
		const pilePositions = [
			{ x: -1.5, z: -1 },
			{ x: 1.5, z: -1 },
			{ x: 0, z: 1.5 },
			{ x: -2, z: 1 },
			{ x: 2, z: 1 },
		];

		for (const pos of pilePositions) {
			const pile = new Group();
			pile.position.set(pos.x, 0, pos.z);

			// Main mound
			const moundGeo = new SphereGeometry(0.35, 10, 6, 0, Math.PI * 2, 0, Math.PI / 2);
			const moundMat = new MeshStandardMaterial({
				color: 0xffffff,
				roughness: 0.95,
				emissive: new Color(NEON_CYAN),
				emissiveIntensity: 0.05,
			});
			const mound = new Mesh(moundGeo, moundMat);
			mound.position.y = 0;
			pile.add(mound);

			// Small snowballs on top
			for (let i = 0; i < 3; i++) {
				const ballGeo = new SphereGeometry(0.08, 8, 6);
				const ball = new Mesh(ballGeo, moundMat.clone());
				ball.position.set(
					(Math.random() - 0.5) * 0.3,
					0.2 + Math.random() * 0.1,
					(Math.random() - 0.5) * 0.3,
				);
				pile.add(ball);
			}

			// Subtle glow
			const gl = new PointLight(NEON_CYAN, 0.15, 2);
			gl.position.y = 0.3;
			pile.add(gl);

			parent.add(pile);
		}
	}

	private initFallingSnow(scene: Object3D): void {
		const snowMat = new MeshBasicMaterial({
			color: 0xffffff,
			transparent: true,
			opacity: 0.7,
		});

		for (let i = 0; i < 200; i++) {
			const size = 0.02 + Math.random() * 0.03;
			const geo = new SphereGeometry(size, 4, 3);
			const flake = new Mesh(geo, snowMat.clone());
			flake.position.set(
				(Math.random() - 0.5) * 40,
				Math.random() * 15,
				(Math.random() - 0.5) * 40,
			);
			scene.add(flake);
			this.snowParticles.push({
				mesh: flake,
				vel: new Vector3(
					(Math.random() - 0.5) * 0.3,
					-0.3 - Math.random() * 0.5,
					(Math.random() - 0.5) * 0.3,
				),
				baseY: flake.position.y,
			});
		}
	}

	update(delta: number): void {
		this.time += delta;

		// Animate falling snow
		for (const sp of this.snowParticles) {
			sp.mesh.position.x += sp.vel.x * delta;
			sp.mesh.position.y += sp.vel.y * delta;
			sp.mesh.position.z += sp.vel.z * delta;

			// Gentle horizontal sway
			sp.mesh.position.x += Math.sin(this.time * 0.5 + sp.baseY) * 0.01;

			// Reset at bottom
			if (sp.mesh.position.y < 0) {
				sp.mesh.position.y = 12 + Math.random() * 3;
				sp.mesh.position.x = (Math.random() - 0.5) * 40;
				sp.mesh.position.z = (Math.random() - 0.5) * 40;
			}
		}

		// Animate aurora lights
		for (let i = 0; i < this.auroraLights.length; i++) {
			const light = this.auroraLights[i];
			const phase = this.time * 0.3 + i * 1.5;
			light.intensity = 0.15 + Math.sin(phase) * 0.15;
			light.position.y = 12 + Math.sin(phase * 0.7) * 3;
		}
	}
}

/**
 * AudioSystem — procedural sound effects using Web Audio API.
 */
import { createSystem } from '@iwsdk/core';
import { gameState, GameState } from './game-state.js';

export class AudioSystem extends createSystem({}) {
	private ctx: AudioContext | null = null;
	private masterGain: GainNode | null = null;
	private ambientNode: OscillatorNode | null = null;
	private ambientGain: GainNode | null = null;
	private initialized = false;

	init(): void {
		// Events
		window.addEventListener('snowball-throw', (e: Event) => {
			const detail = (e as CustomEvent).detail;
			this.playThrow(detail?.isGiant);
		});
		window.addEventListener('snowball-impact', (e: Event) => {
			const detail = (e as CustomEvent).detail;
			this.playImpact(detail?.isGiant);
		});
		window.addEventListener('enemy-hit', (e: Event) => {
			const detail = (e as CustomEvent).detail;
			this.playEnemyHit(detail?.killed);
		});
		window.addEventListener('enemy-throw', () => this.playEnemyThrow());
		window.addEventListener('player-hit', () => this.playPlayerHit());
		window.addEventListener('shield-block', () => this.playShieldBlock());
		window.addEventListener('powerup-collected', () => this.playPowerUp());
		window.addEventListener('wave-start', () => this.playWaveStart());
		window.addEventListener('wave-complete', () => this.playWaveComplete());
		window.addEventListener('game-over', () => this.playGameOver());

		// Init audio on first interaction
		const initAudio = () => {
			if (this.initialized) return;
			this.initAudioContext();
			window.removeEventListener('click', initAudio);
			window.removeEventListener('touchstart', initAudio);
			window.removeEventListener('keydown', initAudio);
		};
		window.addEventListener('click', initAudio);
		window.addEventListener('touchstart', initAudio);
		window.addEventListener('keydown', initAudio);
	}

	private initAudioContext(): void {
		try {
			this.ctx = new AudioContext();
			this.masterGain = this.ctx.createGain();
			this.masterGain.gain.value = 0.3;
			this.masterGain.connect(this.ctx.destination);
			this.initialized = true;
			this.startAmbient();
		} catch {}
	}

	private startAmbient(): void {
		if (!this.ctx || !this.masterGain) return;

		// Quiet wind-like ambient
		this.ambientGain = this.ctx.createGain();
		this.ambientGain.gain.value = 0.03;
		this.ambientGain.connect(this.masterGain);

		// Use buffer noise for wind
		const bufferSize = this.ctx.sampleRate * 2;
		const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
		const data = buffer.getChannelData(0);
		for (let i = 0; i < bufferSize; i++) {
			data[i] = (Math.random() * 2 - 1) * 0.5;
		}

		const noise = this.ctx.createBufferSource();
		noise.buffer = buffer;
		noise.loop = true;

		const filter = this.ctx.createBiquadFilter();
		filter.type = 'lowpass';
		filter.frequency.value = 300;

		noise.connect(filter);
		filter.connect(this.ambientGain);
		noise.start();
	}

	private playNote(freq: number, duration: number, type: OscillatorType = 'sine', vol = 0.15): void {
		if (!this.ctx || !this.masterGain) return;
		const t = this.ctx.currentTime;
		const osc = this.ctx.createOscillator();
		const gain = this.ctx.createGain();
		osc.type = type;
		osc.frequency.setValueAtTime(freq, t);
		gain.gain.setValueAtTime(vol, t);
		gain.gain.exponentialRampToValueAtTime(0.001, t + duration);
		osc.connect(gain);
		gain.connect(this.masterGain);
		osc.start(t);
		osc.stop(t + duration);
	}

	private playNoise(duration: number, freq: number, vol = 0.1): void {
		if (!this.ctx || !this.masterGain) return;
		const t = this.ctx.currentTime;
		const bufferSize = Math.floor(this.ctx.sampleRate * duration);
		const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
		const data = buffer.getChannelData(0);
		for (let i = 0; i < bufferSize; i++) {
			data[i] = (Math.random() * 2 - 1);
		}
		const src = this.ctx.createBufferSource();
		src.buffer = buffer;
		const filter = this.ctx.createBiquadFilter();
		filter.type = 'bandpass';
		filter.frequency.value = freq;
		filter.Q.value = 1;
		const gain = this.ctx.createGain();
		gain.gain.setValueAtTime(vol, t);
		gain.gain.exponentialRampToValueAtTime(0.001, t + duration);
		src.connect(filter);
		filter.connect(gain);
		gain.connect(this.masterGain!);
		src.start(t);
	}

	private playThrow(isGiant: boolean): void {
		// Whoosh sound
		this.playNoise(0.25, isGiant ? 600 : 1200, 0.12);
		this.playNote(isGiant ? 200 : 400, 0.15, 'sine', 0.08);
	}

	private playImpact(isGiant: boolean): void {
		// Soft thud + crunch
		this.playNoise(0.3, isGiant ? 400 : 800, 0.15);
		this.playNote(isGiant ? 80 : 120, 0.2, 'sine', 0.1);
	}

	private playEnemyHit(killed: boolean): void {
		if (killed) {
			// Satisfying poof
			this.playNote(880, 0.1, 'sine', 0.12);
			this.playNote(1100, 0.15, 'sine', 0.1);
			this.playNoise(0.2, 2000, 0.08);
		} else {
			// Hit thunk
			this.playNote(330, 0.1, 'triangle', 0.1);
			this.playNoise(0.15, 1500, 0.06);
		}
	}

	private playEnemyThrow(): void {
		this.playNoise(0.15, 600, 0.04);
	}

	private playPlayerHit(): void {
		// Pain/damage sound
		this.playNote(200, 0.3, 'sawtooth', 0.15);
		this.playNote(150, 0.4, 'sine', 0.1);
	}

	private playShieldBlock(): void {
		// Metallic ping
		this.playNote(1200, 0.15, 'sine', 0.12);
		this.playNote(1800, 0.1, 'sine', 0.08);
	}

	private playPowerUp(): void {
		// Rising chime
		this.playNote(440, 0.1, 'sine', 0.1);
		setTimeout(() => this.playNote(660, 0.1, 'sine', 0.1), 80);
		setTimeout(() => this.playNote(880, 0.15, 'sine', 0.12), 160);
	}

	private playWaveStart(): void {
		// Alert fanfare
		this.playNote(440, 0.15, 'square', 0.08);
		setTimeout(() => this.playNote(550, 0.15, 'square', 0.08), 120);
		setTimeout(() => this.playNote(660, 0.2, 'square', 0.1), 240);
	}

	private playWaveComplete(): void {
		// Victory jingle
		this.playNote(523, 0.15, 'sine', 0.12);
		setTimeout(() => this.playNote(659, 0.15, 'sine', 0.12), 100);
		setTimeout(() => this.playNote(784, 0.15, 'sine', 0.12), 200);
		setTimeout(() => this.playNote(1047, 0.3, 'sine', 0.15), 300);
	}

	private playGameOver(): void {
		// Descending tones
		this.playNote(440, 0.3, 'sawtooth', 0.1);
		setTimeout(() => this.playNote(330, 0.3, 'sawtooth', 0.1), 250);
		setTimeout(() => this.playNote(220, 0.5, 'sawtooth', 0.12), 500);
	}

	update(): void {
		// Audio context resume if needed
		if (this.ctx && this.ctx.state === 'suspended') {
			this.ctx.resume();
		}
	}
}

